package com.bjjj.todo;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.webkit.*;import android.widget.Toast;import org.json.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 WebView web;boolean create;final Handler syncHandler=new Handler(Looper.getMainLooper());final Runnable syncLoop=new Runnable(){public void run(){if(!CloudSync.busy)CloudSync.executor.execute(()->{try{CloudSync.run(getApplicationContext());}catch(Exception ignored){}});syncHandler.postDelayed(this,15000);}};
 public void onCreate(Bundle state){super.onCreate(state);create=getIntent().getBooleanExtra("create",false);web=new WebView(this);web.setBackgroundColor(0xff0d1a20);web.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});if(Build.VERSION.SDK_INT<30)web.setFitsSystemWindows(true);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setJavaScriptCanOpenWindowsAutomatically(false);web.addJavascriptInterface(new Bridge(),"Native");web.setWebChromeClient(new WebChromeClient(){public boolean onJsConfirm(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("删除",(d,w)->result.confirm()).setNegativeButton("取消",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}});web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}public void onPageFinished(WebView v,String url){if(create){v.evaluateJavascript("editTask()",null);create=false;}}});try{String html=new java.util.Scanner(getAssets().open("index.html"),"UTF-8").useDelimiter("\\A").next();html=html.replace("<!--CLOUD_UI-->","<style>"+new java.util.Scanner(getAssets().open("cloud-ui.css"),"UTF-8").useDelimiter("\\A").next()+"</style><script>"+new java.util.Scanner(getAssets().open("cloud-ui.js"),"UTF-8").useDelimiter("\\A").next()+"</script>");String calendarCss=new java.util.Scanner(getAssets().open("mobile-calendar.css"),"UTF-8").useDelimiter("\\A").next();String calendarJs=new java.util.Scanner(getAssets().open("month-calendar.js"),"UTF-8").useDelimiter("\\A").next()+"\n"+new java.util.Scanner(getAssets().open("mobile-calendar.js"),"UTF-8").useDelimiter("\\A").next();html=html.replace("<!--CALENDAR_UI-->","<style>"+calendarCss+"</style><script>"+calendarJs+"</script>");web.loadDataWithBaseURL("https://bjjj.invalid/",html,"text/html","UTF-8",null);}catch(Exception e){throw new IllegalStateException(e);}Reminder.schedule(this);}
 protected void onResume(){super.onResume();syncHandler.removeCallbacks(syncLoop);syncHandler.postDelayed(syncLoop,15000);if(web!=null)web.evaluateJavascript("if(window.refresh)refresh()",null);TodoWidget.updateAll(this);Reminder.schedule(this);CloudSync.schedule(this);CloudSync.executor.execute(()->{try{CloudSync.run(getApplicationContext());}catch(Exception ignored){}});}
 public void onRequestPermissionsResult(int r,String[] permissions,int[] result){super.onRequestPermissionsResult(r,permissions,result);Reminder.schedule(this);if(web!=null)web.evaluateJavascript("refresh()",null);}
 class Bridge {
  @JavascriptInterface public void cloud(String action,String data,String id){CloudSync.executor.execute(()->{JSONObject response=new JSONObject();try{response.put("ok",true).put("data",CloudSync.handle(getApplicationContext(),action,new JSONObject(data)));}catch(Exception e){try{response.put("ok",false).put("error",e.getMessage());}catch(Exception ignored){}}String encoded=response.toString();runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.cloudResolve("+JSONObject.quote(id)+","+encoded+")",null);});});}

  @JavascriptInterface public String call(String action,String data){try{JSONObject p=new JSONObject(data),result=new JSONObject();switch(action){
   case "get": result=Store.read(MainActivity.this);result.put("cloudStatus",CloudSync.status(MainActivity.this));result.put("notifications",Reminder.allowed(MainActivity.this));result.put("exact",Build.VERSION.SDK_INT<31||getSystemService(AlarmManager.class).canScheduleExactAlarms());break;
   case "save":Store.save(MainActivity.this,p);Store.changed(MainActivity.this);break;
   case "done":Store.done(MainActivity.this,p.getString("id"),p.getBoolean("done"));Store.changed(MainActivity.this);break;
   case "delete":Store.delete(MainActivity.this,p.getString("id"));Store.changed(MainActivity.this);break;
   case "settings":synchronized(Store.class){JSONObject r=Store.read(MainActivity.this);r.getJSONObject("settings").put("opacity",Math.max(0,Math.min(100,p.getInt("opacity"))));Store.write(MainActivity.this,r);}TodoWidget.updateAll(MainActivity.this);break;
   case "pin":runOnUiThread(()->{String message;try{AppWidgetManager m=AppWidgetManager.getInstance(MainActivity.this);boolean requested=m.isRequestPinAppWidgetSupported()&&m.requestPinAppWidget(new ComponentName(MainActivity.this,TodoWidget.class),null,null);message=requested?"已向桌面发出添加请求。这不代表已经添加；如果没有弹窗，请按下方说明手动添加。":"当前手机桌面不接受快捷添加请求，请按下方说明手动添加。";}catch(Exception e){message="手机桌面未能处理添加请求，请按下方说明手动添加。";}web.evaluateJavascript("window.pinResult("+JSONObject.quote(message)+")",null);});break;
   case "home":runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME));}catch(Exception e){Toast.makeText(MainActivity.this,"请按手机Home键回到桌面",Toast.LENGTH_LONG).show();}});break;
   case "notification":runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},10);else startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));});break;
   case "exact":runOnUiThread(()->{if(Build.VERSION.SDK_INT>=31)startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));});break;
   default:throw new Exception("不支持的操作");
  }return new JSONObject().put("ok",true).put("data",result).toString();}catch(Exception e){try{return new JSONObject().put("ok",false).put("error",e.getMessage()).toString();}catch(Exception ignored){return "{\"ok\":false}";}}}
 }
 protected void onPause(){syncHandler.removeCallbacks(syncLoop);super.onPause();}
 protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("Native");web.destroy();}super.onDestroy();}
}
